CREATE TABLE o(x INT);
INSERT INTO o VALUES (1), (2);
CREATE TABLE r(x INT);
INSERT INTO r VALUES (1), (5);
CREATE TABLE l(x INT, y INT);
INSERT INTO l VALUES (2, 5), (3, 7);
CREATE TABLE e(x INT);
CREATE TABLE b(k INT, j TEXT);
INSERT INTO b VALUES (1,'[1,2]'),(2,'[2,3]'),(3,'[]');
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON NULL WHERE (SELECT count(*) FROM r WHERE r.x IN (SELECT l.y FROM l WHERE b.x <= l.x));
SELECT a.x, b.x FROM o AS a RIGHT JOIN o AS b ON NULL WHERE (SELECT count(*) FROM r WHERE r.x IN (SELECT l.y FROM l WHERE b.x <= l.x));
SELECT a.x, b.x FROM o AS a JOIN o AS c RIGHT JOIN o AS b ON NULL WHERE (SELECT count(*) FROM r WHERE r.x IN (SELECT l.y FROM l WHERE b.x <= l.x));
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON a.x = b.x + 1 WHERE EXISTS (SELECT 1 FROM r WHERE r.x IN (SELECT l.y FROM l WHERE b.x <= l.x));
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON a.x = b.x + 1 WHERE b.x IN (SELECT r.x FROM r WHERE r.x IN (SELECT l.y FROM l WHERE l.x >= r.x));
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON a.x = b.x + 1 WHERE b.x NOT IN (SELECT r.x FROM r WHERE r.x IN (SELECT l.y FROM l WHERE l.x = r.x));
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON NULL WHERE (SELECT count(*) FROM r WHERE r.x < (SELECT max(l.y) FROM l WHERE l.x >= r.x));
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON NULL WHERE (SELECT count(*) FROM r WHERE r.x < (SELECT max(l.y) FROM l WHERE l.x = r.x + b.x));
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON NULL WHERE (SELECT count(*) FROM r WHERE r.x >= (SELECT sum(l.y) FROM l WHERE l.x = b.x));
SELECT b.k FROM o AS a FULL JOIN b ON a.x = b.k WHERE EXISTS (SELECT 1 FROM json_each(b.j) WHERE value = b.k);
SELECT b.k, (SELECT count(*) FROM json_each(b.j)) FROM o AS a FULL JOIN b ON a.x = b.k WHERE (SELECT count(*) FROM json_each(b.j)) > 1;
SELECT b.k FROM e AS a FULL JOIN b ON a.x = b.k WHERE b.k IN (SELECT r.x FROM r JOIN l ON r.x = l.y - 4);
SELECT a.x, b.x FROM e AS a FULL JOIN o AS b ON a.x = b.x WHERE EXISTS (SELECT 1 FROM r JOIN l ON r.x = l.y);
SELECT a.x, b.x FROM e AS a FULL JOIN o AS b ON a.x = b.x WHERE b.x IN (SELECT l.x FROM r JOIN l ON r.x = l.y) AND EXISTS (SELECT 1 FROM r JOIN l ON r.x = l.y);
WITH c(x) AS MATERIALIZED (SELECT x FROM o) SELECT a.x, b.x FROM e AS a FULL JOIN o AS b ON a.x = b.x WHERE b.x IN (SELECT x FROM c) AND EXISTS (SELECT 1 FROM c WHERE c.x = b.x);
WITH c(x) AS (SELECT x FROM o WHERE x > 1) SELECT a.x, b.x FROM e AS a FULL JOIN o AS b ON a.x = b.x WHERE b.x IN (SELECT x FROM c) AND (SELECT count(*) FROM c WHERE c.x = b.x) = 1;
SELECT a.x, b.x FROM o AS a FULL JOIN o AS b ON NULL WHERE (SELECT count(*) FROM r WHERE r.x IN (SELECT l.y FROM l WHERE b.x <= l.x) AND r.x IN (SELECT l.y FROM l WHERE b.x <= l.x)) OR b.x = 7;
SELECT a.x, b.x, d.x FROM o AS a FULL JOIN o AS b ON NULL FULL JOIN o AS d ON b.x = d.x WHERE (SELECT count(*) FROM r WHERE r.x IN (SELECT l.y FROM l WHERE d.x <= l.x));
